mapper.select:
/* getAsList 쿼리 조회속도개선 튜닝완료 2020.07.06. crm_as_mgt_answer테이블 인덱스추가 */ SELECT out_tb.*, (SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'AS' AND z.p_code = 'CD01' AND z.code = out_tb.proc_status ) AS proc_status_nm, /* 처리상태 명칭 */ (SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'AS' AND z.p_code = 'CD02' AND z.code = out_tb.accept_route ) AS accept_route_nm, /* 접수경로 명칭 */ (SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'AS' AND z.p_code = 'CD07' AND z.code = out_tb.request_type ) AS request_type_nm, /* 문의유형 명칭 */ (SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'AS' AND z.p_code = 'CD03' AND z.code = out_tb.service_cate ) AS service_cate_nm, /* 시스템(대) 명칭 */ (SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'AS' AND z.p_code = out_tb.service_cate AND z.code = out_tb.inquiry_type ) AS inquiry_type_nm, /* 시스템(소) 명칭 */ (SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'AS' AND z.p_code = 'CD04' AND z.code = out_tb.inportance ) AS inportance_nm, /* 중요도 명칭 */ (SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'AS' AND z.p_code = 'CD05' AND z.code = out_tb.cause_type ) AS cause_type_nm, /* 원인유형 명칭 */ (SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'AS' AND z.p_code = 'CD06' AND z.code = out_tb.action_type ) AS action_type_nm, /* 조치유형 명칭 */ (SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'AS' AND z.p_code = 'CD09' AND z.CODE = out_tb.proc_gubun) AS proc_gubun_nm, /*처리구분 명칭 */ out_tb.w_content ,/* 고객 최종 코멘트 */ TO_CHAR(TO_DATE(out_tb.complete_dt,'yyyyMMdd'),'yyyy-MM-dd') as_complete_dt, /*처리완료일*/ TO_CHAR(TO_DATE(out_tb.accept_dt,'yyyyMMdd'),'yyyy-MM-dd') as_accept_dt, /*접수일*/ TO_CHAR(TO_DATE(out_tb.proc_dt,'yyyyMMdd'),'yyyy-MM-dd') as_proc_dt, /*처리완료예정일*/ TO_CHAR(out_tb.star_state_date,'yyyy-MM-dd') star_state_date, (SELECT count(crm_as_mgt_answer.seq)FROM crm_as_mgt_answer WHERE as_no = out_tb.as_no ) AS total_aws_cnt, /* 고객 답변수 */ (SELECT decode(w_gubun, 'U', 1, 0)FROM crm_as_mgt_answer WHERE SEQ = (select MAX(SEQ) from crm_as_mgt_answer where AS_NO=out_tb.as_no) AND AS_NO = out_tb.as_no ) AS aws_cnt, CASE WHEN AS_NO_LINK IS NULL OR TRIM(AS_NO_LINK) = '' THEN 0 ELSE LENGTH(AS_NO_LINK) - LENGTH(REPLACE(AS_NO_LINK, ',', '')) + 1 END AS AS_NO_LINK_COUNT FROM ( SELECT in_tb.*, ROW_NUMBER() OVER( ORDER BY in_tb.as_no ASC) AS rnum FROM ( SELECT a.proc_dt, a.as_no, a.cn_as_no, a.as_no_link, a.apply_nm, a.proc_status, /* 처리상태 C */ a.cust_code, /* 거래처 코드 (cust_code) */ b.cust_kor_name, /* 거래처명 */ a.accept_route, /* 접수경로 C */ a.request_type, /* 문의유형 C */ a.service_cate, /* 시스템(대) C */ a.inquiry_type, /* 시스템(소) C */ a.inportance, /* 중요도 C */ a.tel_confirm, /* 전화확인 완료 C */ a.tel_absence, /* 전화 부재중 C */ a.tel_absence_cnt, /* 전화 부재중 횟수 C */ a.cause_type, /* 원인유형 C */ a.action_type, /* 조치유형 C */ a.assign_id, /* 처리담당자 아이디 */ a.star_state, /* 고객평가 */ a.call_content, /* 요청내용 */ b.erp_code, b.priority, /*우선처*/ a.del_yn, a.accept_dt, a.star_state_date, a.action_content,/* 조치내용 */ a.work_time, /* 작업시간 */ a.complete_dt, /* 처리 예정 일자 */ a.chatbot_id, /* 챗봇상담내역ID */ e.retire_date, /* 퇴사 일자 */ a.rl_apply_nm, /* AS신청자 이름 */ a.proc_gubun, /* 처리구분*/ a.proc_build_info, /* 빌드순번 */ a.proc_test_info, /* 개발처리서(테스트케이스) */ a.proc_process_sp, /* 프로세스정의서 */ a.proc_screen_sp, /* 화면정의서 */ a.proc_table_sp, /* 테이블정의서 */ a.proc_function_sp, /* 기능분해도 */ a.proc_interface_sp, /* 인터페이스정의서 */ NVL((SELECT z.emp_nm FROM crm_emp_mgt z WHERE z.emp_no = a.assign_id ), '-') emp_nm, /* 처리담당자 이름 */ (SELECT z.part_type FROM crm_emp_mgt z WHERE z.emp_no = a.assign_id ) part_type, /* 처리담당자 파트 */ (SELECT Z.DEPT_CD FROM CRM_EMP_MGT Z WHERE Z.EMP_NO = A.ASSIGN_ID) DEPT_CD, (SELECT Z.DEPT_NM FROM CRM_EMP_MGT Z WHERE Z.EMP_NO = A.ASSIGN_ID) DEPT_NM, D.REG_DATE, /* 처리완료일 */ C.w_content /* 고객 최종 코멘트 */ FROM crm_as_mgt a INNER JOIN crm_cust_mgt b ON a.cust_code = b.crm_code LEFT OUTER JOIN ( SELECT C1.AS_NO, C1.w_content FROM crm_as_mgt_answer C1 , (SELECT B.AS_NO, MAX(SEQ) SEQ FROM crm_as_mgt A , crm_as_mgt_answer B WHERE a.AS_NO = b.AS_NO AND A.del_yn IS NULL AND B.w_gubun = 'A' AND B.w_id != '88888' GROUP BY B.AS_NO ) C2 WHERE C1.SEQ = C2.SEQ AND C1.AS_NO = C2.AS_NO ) C ON A.AS_NO = C.AS_NO LEFT OUTER JOIN (SELECT AS_NO , MAX(SEQ) KEEP(DENSE_RANK LAST ORDER BY AS_NO, SEQ) AS SEQ , MAX(REG_DATE) KEEP(DENSE_RANK LAST ORDER BY AS_NO, SEQ) AS REG_DATE FROM CRM_AS_MGT_HIST WHERE 1=1 AND PROC_STATUS = 'C005' GROUP BY AS_NO ) D ON (A.AS_NO = D.AS_NO) LEFT OUTER JOIN KYERP.TB_HR_EMPLOYEE E ON A.ASSIGN_ID = E.EMP_CD WHERE A.del_yn IS NULL ) in_tb WHERE 1=1
) OUT_TB WHERE 1=1
AND RNUM BETWEEN #{startRow} AND #{endRow} ORDER BY AS_NO DESC
ORDER BY AS_NO DESC

SELECT M.AS_NO ,M.CAUSE_TYPE ,M.ACTION_TYPE ,(SELECT CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD05' AND Z.CODE = M.CAUSE_TYPE) AS CAUSE_TYPE_NM ,(SELECT CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD06' AND Z.CODE = M.ACTION_TYPE) AS ACTION_TYPE_NM ,M.APPLY_NM ,M.CALL_CONTENT ,N.ACTION_CONTENT ,(SELECT EMP_NM FROM CRM_EMP_MGT WHERE 1=1 AND EMP_NO = M.ASSIGN_ID) AS ASSIGN_NM FROM CRM_AS_MGT M RIGHT OUTER JOIN CRM_AS_MGT_HIST N ON M.AS_NO = N.AS_NO WHERE 1 = 1 AND M.ACCEPT_DT BETWEEN #{as_str_dt} AND #{as_end_dt} AND M.ASSIGN_ID = #{user_id} AND M.PROC_STATUS = 'C005' AND N.PROC_STATUS = 'C005' AND M.CAUSE_TYPE IS NOT NULL AND M.ACTION_TYPE IS NOT NULL AND N.ACTION_CONTENT IS NOT NULL AND N.REG_ID = #{user_id}
AND M.ACTION_CONTENT LIKE '%' || #{search_text} || '%'
ORDER BY M.AS_NO DESC

