mapper.update:

		UPDATE CRM_OPERATE_MGT
		SET WK_COUNT = WK_COUNT - (SELECT MIN(WK_COUNT)
		                            FROM CRM_OPERATE_MGT
		                            WHERE 1=1
		                            AND REQUEST_TYPE = #{request_type}



						            AND SERVICE_CATE = #{service_cate}
						            AND INQUIRY_TYPE = #{inquiry_type}



		                            AND USE_YN 		 = 'Y'
		                            AND MASTER_YN    = 'Y'
		                            )

		WHERE 1=1
		AND REQUEST_TYPE = #{request_type}



        AND SERVICE_CATE = #{service_cate}
        AND INQUIRY_TYPE = #{inquiry_type}



		AND USE_YN 		 = 'Y'
		AND MASTER_YN    = 'Y'

mapper.select:

        SELECT OUT_TB.WK_EMP_NO, OUT_TB.WK_EMP_NM
		FROM (
		  SELECT WK_EMP_NO,
		        (SELECT EMP_NM
		         FROM CRM_EMP_MGT
		         WHERE EMP_NO = IN_TB.WK_EMP_NO) WK_EMP_NM
		  FROM CRM_OPERATE_MGT IN_TB
		  WHERE 1=1
		  AND IN_TB.WK_COUNT = (
		        SELECT MIN(WK_COUNT)
		        FROM CRM_OPERATE_MGT
		        WHERE 1=1
		        AND USE_YN = 'Y'
		  		AND MASTER_YN = 'Y'
		        AND REQUEST_TYPE = #{request_type}



	            AND SERVICE_CATE = #{service_cate}
	            AND INQUIRY_TYPE = #{inquiry_type}



		  )
		  AND IN_TB.REQUEST_TYPE = #{request_type}



	      AND IN_TB.SERVICE_CATE = #{service_cate}
	      AND IN_TB.INQUIRY_TYPE = #{inquiry_type}



		  AND IN_TB.USE_YN = 'Y'
		  AND IN_TB.MASTER_YN = 'Y'
		  ORDER BY IN_TB.WK_EMP_NO
		) OUT_TB
		WHERE ROWNUM = 1
